from test_directed_thanks import test,observed,solo
for event,token in [('NAME_PLATE_UNIT_ADDED','nameplate99'),('PLAYER_TARGET_CHANGED','target'),('UPDATE_MOUSEOVER_UNIT','mouseover'),('PLAYER_FOCUS_CHANGED','focus')]:
 test('Pending thanks resolves immediately on '+event,observed+"local B=BuffTap; B:ObserveSoloThanks(); local first=B.thanksResolution.first; local oldG,oldE=UnitGUID,UnitExists; UnitExists=function(u) return u=='"+token+"' or oldE(u) end; UnitGUID=function(u) return u=='"+token+"' and 'Player-Driveby' or oldG(u) end; B.thanksUnitEvents.scripts.OnEvent(nil,'"+event+"','"+token+"'); assert(#emotes==1 and emotes[1][2]=='"+token+"'); assert(B.thanksResolution.first==first and B.thanksResolution.matched and B.thanksResolution.events==1); B.thanksUnitEvents.scripts.OnEvent(nil,'"+event+"','"+token+"'); assert(#emotes==1 and not B.thanksEventUnit)")
test('Unrelated unit events do not rescan pending auras',observed+"local B=BuffTap; B:ObserveSoloThanks(); B.ObserveSoloThanks=function() error('unrelated scan') end; B.thanksUnitEvents.scripts.OnEvent(nil,'NAME_PLATE_UNIT_ADDED','nameplate1'); assert(#emotes==0 and B.thanksResolution.events==0)")
for gate in ["combat=true","BuffTap.db.helperThanks=false","IsInGroup=function() return true end"]:
 test('Event retry respects gate '+gate,observed+"local B=BuffTap; B:ObserveSoloThanks(); "+gate+"; local old=UnitGUID; UnitGUID=function(u) return u=='target' and 'Player-Driveby' or old(u) end; B.thanksUnitEvents.scripts.OnEvent(nil,'PLAYER_TARGET_CHANGED'); assert(#emotes==0 and B.thanksResolution.events==0)")
test('Event cannot extend expired ten second window',observed+"local B=BuffTap; B:ObserveSoloThanks(); now=now+10.1; local old=UnitGUID; UnitGUID=function(u) return u=='target' and 'Player-Driveby' or old(u) end; B.thanksUnitEvents.scripts.OnEvent(nil,'PLAYER_TARGET_CHANGED'); assert(#emotes==0 and B.thanksResolution.events==0); B:ObserveSoloThanks(); assert(#emotes==0)")
test('No pending incident means no scan on unit changes',solo+"local B=BuffTap; B.ObserveSoloThanks=function() error('idle scan') end; B.thanksUnitEvents.scripts.OnEvent(nil,'PLAYER_TARGET_CHANGED'); assert(#emotes==0)")
test('Diagnostic first lookup survives retries and timeout without private ID',observed+"local B=BuffTap; B:ObserveSoloThanks(); local first=B.thanksResolution.first; advance(.3); assert(B.thanksResolution.first==first and B.thanksResolution.last.at>first.at); for i=1,55 do advance(.21) end; local text=table.concat(B:SoloThanksDiagnostics(),' '); assert(text:find('Thanks first lookup:',1,true) and text:find('Thanks last lookup:',1,true) and text:find('ever matched=false',1,true)); assert(text:find('window expired',1,true) and not text:find('Player-Driveby',1,true))")
test('Known nameplate departure is recorded but cannot bypass send validation',solo+"local B=BuffTap; B.db.helperThankDelay=2; received(1459,'target'); local c=B.helperThankQueue[1]; assert(c and c.resolution and c.resolution.matched); B.thanksUnitEvents.scripts.OnEvent(nil,'NAME_PLATE_UNIT_REMOVED','target'); assert(c.resolution.departure); local old=UnitGUID; UnitGUID=function(u) return u=='target' and 'Player-Reused' or old(u) end; advance(7); assert(#emotes==0 and c.resolution.outcome=='live identity lost before send')")
test('Failed event observation clears temporary unit hint',observed+"local B=BuffTap; B:ObserveSoloThanks(); local old=UnitGUID; UnitGUID=function(u) return u=='target' and 'Player-Driveby' or old(u) end; B.ObserveSoloThanks=function() error('mock failure') end; B.thanksUnitEvents.scripts.OnEvent(nil,'PLAYER_TARGET_CHANGED'); assert(not B.thanksEventUnit and #emotes==0)")
